import {SoundEngine} from './audio.js';
import {timeline,cueAt,PRACTICE_NAMES} from './guides.js';
import {SessionClock} from './session.js';
import {SceneMedia} from './media.js';
import {NarrationEngine} from './narration.js';
const $=id=>document.getElementById(id),audio=new SoundEngine({report:showAudioIssue}),clock=new SessionClock(),media=new SceneMedia();
const WORLD={water:{name:'물결과 울림',description:'맑은 청록빛 수면 위, 하얀 도자기에 잠시 시선을 둡니다.'},forest:{name:'숲의 숨결 — 제주',description:'비가 갠 아침, 나무 사이로 따뜻한 빛이 스며듭니다.'}};
const state={screen:'home',world:'water',practice:'breath',duration:5,guide:'both',guideMode:'both',soundEnabled:false,preview:null,volume:.35,voiceVolume:.85,audioProblem:false,modal:null,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,controlsAlways:false};
let frame=0,hoverTimer=0,previewToken=0,startToken=0,hideTimer=0,cues=[],lastCue=null,pausedBeforeDialog=false,focusReturn=null;
function announce(text){$('liveStatus').textContent=text;}
function syncMedia(){media.sync(state.screen,state.world,clock.status!=='running'&&state.screen==='session',state.reduced);}
const narration=new NarrationEngine({getContext:()=>audio.ensureContext(),unlock:()=>audio.unlock(),activity:on=>audio.duck(on ? 0.42 : 1),report:voiceReport});
function stopSpeech(){narration.stop();}
function voiceReport(issue){if(issue.type==='error'){state.audioProblem=true;showAudioIssue(issue);caption();}else if(issue.type==='started'){state.audioProblem=false;clearAudioIssue();$('audioSourceStatus').textContent=issue.source+' · 재생 시작 확인(실제 청취 확인은 별도)';}}
let lastAudioIssue=null;
function showAudioIssue(issue){lastAudioIssue=issue;const text=typeof issue==='string'?issue:(issue.message??'소리를 재생하지 못했습니다.')+(issue.code?' ['+issue.code+']':'');for(const id of ['setupAudioError','sessionAudioError'])$(id).querySelector('[data-error-text]').textContent=text;const session=state.screen==='session';$(session?'sessionAudioError':'setupAudioError').classList.remove('hidden');announce(text);if(session&&clock.status==='running')pause();updateDiagnostics();}
function clearAudioIssue(){$('setupAudioError').classList.add('hidden');$('sessionAudioError').classList.add('hidden');}
function updateDiagnostics(){$('audioDiagnosticsText').textContent=JSON.stringify({lastError:lastAudioIssue,context:audio.ctx?.state??'not-created',natural:audio.diagnostics(),narration:narration.diagnostics()},null,2);}
function prepareNarration(){narration.configure(state.practice,state.duration);$('audioSourceStatus').textContent=narration.recorded?'모든 프로그램에 동일한 한국어 안내 목소리':'안내 음성을 준비하지 못했습니다';const key=narration.key;narration.preload().catch(e=>{if(key===narration.key&&state.screen==='settings')showAudioIssue({code:'NARRATION_LOAD',message:'내레이션 파일을 불러오지 못했습니다.',detail:e.message});});}

function stopPreview(){clearTimeout(hoverTimer);previewToken++;audio.stopPreview();state.preview=null;document.querySelectorAll('.gallery-card').forEach(el=>{el.classList.remove('is-previewing');el.querySelector('.preview-label').textContent='8초 미리 듣기';el.querySelector('.card-preview').setAttribute('aria-pressed','false');});}
function display(screen){state.screen=screen;for(const name of ['home','settings','session','end'])$('screen-'+name).classList.toggle('hidden',name!==screen);$('siteHeader').classList.toggle('hidden',['session','end'].includes(screen));$('soundEnable').classList.toggle('hidden',screen!=='home');window.scrollTo(0,0);syncMedia();const title=$('screen-'+screen).querySelector('h1,h2');if(title){title.tabIndex=-1;title.focus({preventScroll:true});}}
function selections(){for(const [attr,value]of Object.entries({'practice':state.practice,'duration':String(state.duration),'guide':state.guide,'guide-in':state.guide,'world-switch':state.world}))document.querySelectorAll(`[data-${attr}]`).forEach(el=>{const on=el.getAttribute('data-'+attr)===value;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on));});document.querySelectorAll('[data-guide-toggle]').forEach(el=>{el.setAttribute('aria-checked',String(state.guide!=='off'));el.textContent=state.guide==='off'?'가이드 꺼짐':'가이드 켜짐';});}
function worldUI(){for(const id of ['settingsCover','screen-session','screen-end']){$(id).classList.toggle('world-water',state.world==='water');$(id).classList.toggle('world-forest',state.world==='forest');}$('settingsWorldName').textContent=WORLD[state.world].name;$('settingsWorldDesc').textContent=WORLD[state.world].description;$('sessionTitle').textContent=WORLD[state.world].name;$('sessionPractice').textContent=PRACTICE_NAMES[state.practice];syncMedia();}
async function enableSound(){try{await audio.unlock();state.soundEnabled=true;$('soundEnableText').textContent='소리 켜짐';$('soundEnable').setAttribute('aria-pressed','true');return true;}catch{announce('소리를 재생할 수 없습니다. 소리 없이도 공간에 머물 수 있습니다.');return false;}}
async function preview(world){if(state.screen!=='home')return;if(state.preview===world){stopPreview();return;}stopPreview();const token=previewToken;if(!await enableSound()||token!==previewToken||state.screen!=='home')return;state.preview=world;const card=document.querySelector(`.gallery-card[data-world="${world}"]`);card.classList.add('is-previewing');card.querySelector('.preview-label').textContent='재생 중';card.querySelector('.card-preview').setAttribute('aria-pressed','true');try{await audio.startPreview(world,()=>{if(token===previewToken)stopPreview();});}catch{stopPreview();announce('미리 듣기를 재생할 수 없습니다.');}}
function choose(world){stopPreview();clearAudioIssue();state.world=world;worldUI();selections();display('settings');audio.ensureContext();prepareNarration();audio.loadRecordings(world).catch(e=>showAudioIssue({code:'AMBIENT_LOAD',message:'자연음 파일을 불러오지 못했습니다.',detail:e.message}));}
function caption(){const cue=cueAt(cues,clock.elapsed),on=state.guide==='text'||state.guide==='both'||state.audioProblem;$('sessionCaption').textContent=on&&cue?cue.text:'';$('sessionCaption').classList.toggle('visible',Boolean(on&&cue));}
function speak(cue){if(['voice','both'].includes(state.guide)&&clock.status==='running')narration.play(cue,clock.elapsed);}
function guideChanged(value){if(value!=='off')state.guideMode=value;state.guide=value;stopSpeech();selections();caption();lastCue=null;}
function processGuide(){const cue=cueAt(cues,clock.elapsed);caption();if(cue?.id!==lastCue){stopSpeech();lastCue=cue?.id??null;if(cue)speak(cue);}}
function updateTime(){const left=Math.ceil(Math.max(0,clock.total-clock.elapsed));$('timeDisplay').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;}
function tick(now){if(state.screen!=='session')return;if(clock.step(now)){finish('complete');return;}if(clock.status==='running'){processGuide();audio.tick(clock.elapsed);updateTime();}frame=requestAnimationFrame(tick);}
function showControls(){clearTimeout(hideTimer);$('sessionStage').classList.remove('controls-hidden');if(!state.controlsAlways&&clock.status==='running'&&!state.modal)hideTimer=setTimeout(()=>{if(!$('sessionControls').contains(document.activeElement))$('sessionStage').classList.add('controls-hidden');},7000);}
async function start(){const token=++startToken;stopPreview();stopSpeech();clearAudioIssue();state.audioProblem=false;narration.configure(state.practice,state.duration);narration.setVolume(state.voiceVolume);
 const practice=state.practice,duration=state.duration;const unlocking=audio.unlock(); // Called synchronously in the user's click.
 const begin=()=>{if(token!==startToken||practice!==state.practice||duration!==state.duration)return;clock.start(state.duration);cues=timeline(state.practice,state.duration);lastCue=null;worldUI();selections();display('session');$('screen-session').classList.remove('paused');updateTime();showControls();audio.startSession(state.world,state.volume).catch(e=>showAudioIssue({code:'AMBIENT_START',message:'자연음 재생을 시작하지 못했습니다.',detail:e.message}));processGuide();cancelAnimationFrame(frame);frame=requestAnimationFrame(tick);if(clock.status==='paused')audio.pause();};
 if(narration.recorded&&['voice','both'].includes(state.guide)){$('startSession').disabled=true;$('startSession').setAttribute('aria-busy','true');try{await Promise.all([unlocking,narration.preload(),audio.loadRecordings(state.world)]);begin();}catch(e){if(token===startToken)showAudioIssue({code:'AUDIO_PREPARE',message:'오디오를 준비하지 못했습니다. 다시 시작해 주세요.',detail:e.message});}finally{$('startSession').disabled=false;$('startSession').removeAttribute('aria-busy');}}
 else{begin();unlocking.catch(e=>showAudioIssue({code:'AUDIO_UNLOCK',message:'소리 재생이 차단되었습니다. 다시 듣기를 눌러 주세요.',detail:e.message}));}
}
function pause(){clock.pause();audio.pause();stopSpeech();$('screen-session').classList.add('paused');showControls();syncMedia();}
function resume(){clock.resume();audio.resume();$('screen-session').classList.remove('paused');lastCue=null;processGuide();showControls();syncMedia();}
function openDialog(name){focusReturn=document.activeElement;$('sessionStage').inert=true;pausedBeforeDialog=clock.status==='paused';state.modal=name;pause();$('pauseOverlay').classList.add('hidden');$(name+'Overlay').classList.remove('hidden');selections();$('ambientVolume').value=state.volume*100;$('volumeLabel').textContent=Math.round(state.volume*100)+'%';$('voiceVolume').value=state.voiceVolume*100;$('voiceVolumeLabel').textContent=Math.round(state.voiceVolume*100)+'%';updateDiagnostics();$('motionToggle').checked=state.reduced;$('controlsToggle').checked=state.controlsAlways;$(name+'Overlay').querySelector('button').focus();}
function closeDialog(){const name=state.modal;$('sessionStage').inert=false;$(name+'Overlay').classList.add('hidden');state.modal=null;if(pausedBeforeDialog&&name!=='pause'){$('sessionStage').inert=true;state.modal='pause';$('pauseOverlay').classList.remove('hidden');$('resumeFromOverlay').focus();}else resume();if(!state.modal)focusReturn?.focus();}
function finish(reason){$('sessionStage').inert=false;++startToken;clock.end();if(reason==='complete'&&clock.elapsed<clock.total)return;clearTimeout(hideTimer);cancelAnimationFrame(frame);stopPreview();audio.destroy();stopSpeech();state.modal=null;for(const id of ['pauseOverlay','optionsOverlay','exitOverlay'])$(id).classList.add('hidden');const early=clock.reason==='early';$('endTitle').textContent=early?'여기에서 마무리해도 괜찮아요.':'잠시 머물렀던 시간을 그대로 두어도 괜찮아요.';$('endSub').textContent=early?'언제든 다시 이 공간을 찾아올 수 있습니다.':'지금의 마음을 잠깐 살펴보아도 좋습니다.';$('endEyebrow').textContent='A MOMENT TO BE';display('end');}
function home(){$('sessionStage').inert=false;++startToken;stopPreview();audio.destroy();stopSpeech();cancelAnimationFrame(frame);clock.reset();state.modal=null;clearTimeout(hideTimer);display('home');}
$('soundEnable').onclick=()=>{if(state.soundEnabled){state.soundEnabled=false;stopPreview();$('soundEnableText').textContent='소리 활성화';$('soundEnable').setAttribute('aria-pressed','false');}else enableSound();};
for(const card of document.querySelectorAll('.gallery-card')){const world=card.dataset.world;card.addEventListener('pointerenter',e=>{if(e.pointerType==='touch'||!state.soundEnabled||state.screen!=='home')return;clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>{if(state.screen==='home'&&state.preview!==world)preview(world);},700);});card.addEventListener('pointerleave',()=>{clearTimeout(hoverTimer);if(state.preview===world)stopPreview();});}
document.querySelectorAll('[data-action="choose"]').forEach(el=>el.onclick=()=>choose(el.dataset.world));document.querySelectorAll('[data-action="preview"]').forEach(el=>el.onclick=e=>{e.stopPropagation();preview(el.dataset.world);});
for(const attr of ['practice','duration','guide'])document.querySelectorAll(`[data-${attr}]`).forEach(el=>el.onclick=()=>{if(attr==='guide')guideChanged(el.dataset.guide);else{stopSpeech();state[attr]=attr==='duration'?Number(el.dataset.duration):el.dataset.practice;}selections();prepareNarration();});
document.querySelectorAll('[data-guide-in]').forEach(el=>el.onclick=()=>guideChanged(el.dataset.guideIn));
document.querySelectorAll('[data-world-switch]').forEach(el=>el.onclick=()=>{if(state.world===el.dataset.worldSwitch)return;state.world=el.dataset.worldSwitch;worldUI();selections();audio.switchWorld(state.world,clock.elapsed).catch(e=>showAudioIssue({code:'WORLD_AUDIO',message:'공간의 소리를 바꾸지 못했습니다.',detail:e.message}));});
$('startSession').onclick=start;$('backGallery').onclick=home;$('goHome').onclick=home;$('endHome').onclick=home;
$('switchWorldInSettings').onclick=()=>{state.world=state.world==='water'?'forest':'water';worldUI();};
$('pauseResume').onclick=()=>openDialog('pause');$('resumeFromOverlay').onclick=()=>{pausedBeforeDialog=false;closeDialog();};$('exitFromPause').onclick=()=>openDialog('exit');
$('sessionOptionsBtn').onclick=()=>openDialog('options');$('closeOptions').onclick=closeDialog;$('sessionExitBtn').onclick=()=>openDialog('exit');$('cancelExit').onclick=closeDialog;$('confirmExit').onclick=()=>finish('early');
$('ambientVolume').oninput=e=>{state.volume=Number(e.target.value)/100;audio.setVolume(state.volume);$('volumeLabel').textContent=e.target.value+'%';};$('motionToggle').onchange=e=>{state.reduced=e.target.checked;$('screen-session').classList.toggle('reduce-motion',state.reduced);syncMedia();};$('controlsToggle').onchange=e=>{state.controlsAlways=e.target.checked;showControls();};
$('showControlsBtn').onclick=showControls;$('sessionStage').onpointermove=showControls;$('sessionStage').onpointerdown=showControls;$('sessionControls').onfocusin=showControls;
$('voiceVolume').oninput=e=>{state.voiceVolume=Number(e.target.value)/100;narration.setVolume(state.voiceVolume);$('voiceVolumeLabel').textContent=e.target.value+'%';};
$('testVoice').onclick=()=>{stopPreview();clearAudioIssue();state.audioProblem=false;narration.configure(state.practice,state.duration);narration.setVolume(state.voiceVolume);audio.unlock().catch(e=>showAudioIssue({code:'AUDIO_UNLOCK',message:e.message}));const sample=timeline(state.practice,state.duration)[0];narration.play(sample,sample.at);};
$('retrySessionAudio').onclick=()=>{clearAudioIssue();state.audioProblem=false;audio.unlock().catch(e=>showAudioIssue({code:'AUDIO_UNLOCK',message:e.message}));audio.startSession(state.world,state.volume,clock.elapsed).catch(e=>showAudioIssue({code:'AMBIENT_START',message:e.message}));resume();};
$('continueWithCaptions').onclick=()=>{clearAudioIssue();state.audioProblem=false;guideChanged('text');resume();};
$('audioDiagnostics').ontoggle=updateDiagnostics;
$('openAbout').onclick=()=>{focusReturn=document.activeElement;$('aboutDialog').classList.remove('hidden');$('closeAbout').focus();};function closeAbout(){$('aboutDialog').classList.add('hidden');focusReturn?.focus();}$('closeAbout').onclick=closeAbout;$('aboutDialog').onclick=e=>{if(e.target===$('aboutDialog'))closeAbout();};
document.addEventListener('keydown',e=>{const dialog=[...document.querySelectorAll('[role="dialog"]')].find(el=>!el.classList.contains('hidden'));if(dialog){if(e.key==='Escape'){if(dialog.id==='aboutDialog')closeAbout();else{if(state.modal==='pause')pausedBeforeDialog=false;closeDialog();}}if(e.key==='Tab'){const buttons=[...dialog.querySelectorAll('button,a,input')].filter(el=>!el.disabled);const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPreview();if(state.screen==='session'&&clock.status==='running'){openDialog('pause');announce('화면을 떠나 명상을 잠시 멈추었습니다.');}}});window.addEventListener('pagehide',()=>{audio.destroy();stopSpeech();});
selections();worldUI();

document.querySelectorAll('[data-guide-toggle]').forEach(el=>el.onclick=()=>guideChanged(state.guide==='off'?state.guideMode:'off'));
